static void
gk_species_damping_forward_euler_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, const struct gkyl_array *fin,
  const struct gkyl_array *fbar_in, struct gkyl_array *fbar_out, double dt
