// Same arithmetic as gk_species_step_f_dynamic; avoid constructing a full app.
void gk_species_step_f(struct gk_species *species, struct gkyl_array *out,
                       double dt, const struct gkyl_array *inp) {
  gkyl_array_accumulate(gkyl_array_scale(out, dt), 1.0, inp);
}

static void
filter_euler(struct gkyl_gyrokinetic_app *app, struct gk_species *species,
             const struct gkyl_array *fin, const struct gkyl_array *bar_in,
             struct gkyl_array *fout, struct gkyl_array *bar_out,
             struct gkyl_array *buffer, struct gkyl_array *cfl, double dt) {
  gkyl_array_clear(fout, 0.0);
  gkyl_array_clear(cfl, 0.0);
  gk_species_damping_advance(app, species, &species->damping, 0, fin, bar_in,
                             buffer, fout, cfl);
  // An exactly conservative transfer between two equal-volume cells.
  // Divide by M here so the physical RHS after multiplication is (-1,+1).
  for (int cell = 0; cell < 2; ++cell) {
    double *rhs = gkyl_array_fetch(fout, cell);
    const double *mult = gkyl_array_cfetch(species->fdot_mult.multiplier, cell);
    rhs[0] += (cell == 0 ? -1.0 : 1.0) / mult[0];
  }
  gk_species_fdot_multiplier_advance_times_rate(
      app, species, &species->fdot_mult, 0, fin, fout);
  gk_species_step_f(species, fout, dt, fin);
  gk_species_damping_forward_euler_enabled(app, species, fin, bar_in, bar_out,
                                           dt);
}

static double number(const struct gkyl_array *arr) {
  const double *left = gkyl_array_cfetch(arr, 0);
  const double *right = gkyl_array_cfetch(arr, 1);
  return left[0] + right[0];
}

